import random
from datetime import datetime

import pandas as pd
import streamlit as st
from streamlit_autorefresh import st_autorefresh

from ui_theme import apply_theme

apply_theme()

st.title("Crew & environment")
st.caption("Live simulated telemetry from astronaut-worn and spacecraft sensors.")

# This is a simulation for the prototype. It does not connect to physical sensors.
st.info(
    "SIMULATION MODE — readings are generated by software to demonstrate an "
    "automated sensor-monitoring system. No physical sensors are connected."
)

st.session_state.setdefault("crew_readings", [])
st.session_state.setdefault("cosmo_sensor_running", False)
st.session_state.setdefault("cosmo_sensor_values", {
    "heart_rate_bpm": 70.0,
    "sleep_hours": 7.5,
    "activity_demo_index": 42,
    "oxygen_percent": 20.9,
    "co2_ppm": 1100.0,
    "temperature_c": 22.0,
    "humidity_percent": 45.0,
    "pressure_kpa": 101.0,
})

control_left, control_right, control_info = st.columns([1, 1, 2])
with control_left:
    if st.button(
        "Stop simulation" if st.session_state.cosmo_sensor_running else "Start live simulation",
        type="primary",
        use_container_width=True,
    ):
        st.session_state.cosmo_sensor_running = not st.session_state.cosmo_sensor_running
        st.rerun()
with control_right:
    if st.button("Reset simulated readings", use_container_width=True):
        st.session_state.cosmo_sensor_running = False
        st.session_state.cosmo_sensor_values = {
            "heart_rate_bpm": 70.0,
            "sleep_hours": 7.5,
            "activity_demo_index": 42,
            "oxygen_percent": 20.9,
            "co2_ppm": 1100.0,
            "temperature_c": 22.0,
            "humidity_percent": 45.0,
            "pressure_kpa": 101.0,
        }
        st.session_state.crew_readings = []
        st.rerun()
with control_info:
    if st.session_state.cosmo_sensor_running:
        st.success("Sensor simulation running · updating every 3 seconds")
    else:
        st.warning("Simulation paused · press Start live simulation")

def drift(value, amount, low, high, decimals=1):
    return round(max(low, min(high, value + random.uniform(-amount, amount))), decimals)

def generate_sensor_snapshot():
    values = st.session_state.cosmo_sensor_values
    values["heart_rate_bpm"] = drift(values["heart_rate_bpm"], 2.8, 52, 115, 1)
    values["sleep_hours"] = drift(values["sleep_hours"], 0.03, 4.0, 10.0, 1)
    values["activity_demo_index"] = int(drift(values["activity_demo_index"], 5, 5, 95, 0))
    values["oxygen_percent"] = drift(values["oxygen_percent"], 0.08, 19.0, 21.5, 2)
    values["co2_ppm"] = drift(values["co2_ppm"], 45, 500, 5000, 0)
    values["temperature_c"] = drift(values["temperature_c"], 0.15, 18, 28, 1)
    values["humidity_percent"] = drift(values["humidity_percent"], 0.8, 25, 65, 1)
    values["pressure_kpa"] = drift(values["pressure_kpa"], 0.12, 95, 105, 2)

    snapshot = {
        "timestamp": datetime.now().isoformat(timespec="seconds"),
        "astronaut_id": "AST-001",
        "source": "Simulated sensor",
        **values.copy(),
    }
    st.session_state.crew_readings.append(snapshot)
    # Keep the demo history bounded during a long-running session.
    st.session_state.crew_readings = st.session_state.crew_readings[-200:]

if st.session_state.cosmo_sensor_running:
    generate_sensor_snapshot()
    st_autorefresh(interval=3000, limit=None, key="cosmo_sensor_refresh")

values = st.session_state.cosmo_sensor_values
st.subheader("Crew physiological sensors")
a, b, c = st.columns(3)
a.metric("Heart rate", f'{values["heart_rate_bpm"]:.1f} bpm', help="Simulated wearable heart-rate sensor")
b.metric("Sleep estimate", f'{values["sleep_hours"]:.1f} h', help="Simulated 24-hour sleep estimate")
c.metric("Activity index", f'{values["activity_demo_index"]}/100', help="Simulated wearable activity estimate")

st.subheader("Spacecraft environmental sensors")
a, b, c, d, e = st.columns(5)
a.metric("Oxygen", f'{values["oxygen_percent"]:.2f} %')
b.metric("Carbon dioxide", f'{values["co2_ppm"]:.0f} ppm')
c.metric("Temperature", f'{values["temperature_c"]:.1f} °C')
d.metric("Humidity", f'{values["humidity_percent"]:.1f} %')
e.metric("Cabin pressure", f'{values["pressure_kpa"]:.2f} kPa')

st.subheader("Sensor status")
sensor_names = [
    "Wearable heart-rate sensor",
    "Sleep/activity estimation",
    "Cabin oxygen sensor",
    "Cabin CO₂ sensor",
    "Cabin temperature sensor",
    "Cabin humidity sensor",
    "Cabin pressure sensor",
]
status_cols = st.columns(4)
for index, sensor_name in enumerate(sensor_names):
    with status_cols[index % 4]:
        st.caption(f"🟢 Simulated · {sensor_name}")

if st.session_state.crew_readings:
    history = pd.DataFrame(st.session_state.crew_readings)
    st.subheader("Live telemetry trends")
    chart_cols = st.columns(2)
    with chart_cols[0]:
        st.caption("Crew heart rate")
        st.line_chart(history.set_index("timestamp")[["heart_rate_bpm"]], height=190)
    with chart_cols[1]:
        st.caption("Cabin CO₂")
        st.line_chart(history.set_index("timestamp")[["co2_ppm"]], height=190)
    with st.expander("View recent sensor records"):
        st.dataframe(history.tail(20), use_container_width=True, hide_index=True)
    st.download_button(
        "Export simulated telemetry (CSV)",
        history.to_csv(index=False).encode("utf-8"),
        "cosmo_care_simulated_telemetry.csv",
        "text/csv",
    )
else:
    st.info("Start the simulation to generate sensor readings and telemetry trends.")

st.caption(
    "Demonstration only. These generated values are not real astronaut measurements, "
    "medical assessments, or evidence that spacecraft conditions are safe."
)
